parameters.jsCode:
const responseRaw = $input.first().json.choices[0].message.content;
let data;
try {
  data = JSON.parse(responseRaw);
} catch (e) {
  data = {};
}

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'short',
  day: 'numeric'
});

// 1. Stories HTML
let storiesHtml = '';
for (const item of (data.top_stories || []).slice(0, 3)) {
  storiesHtml += `
    <div style="background-color: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 18px; margin-bottom: 16px;">
      <span style="display: inline-block; background-color: #eff6ff; color: #1d4ed8; font-size: 11px; font-weight: 700; text-transform: uppercase; padding: 3px 8px; border-radius: 4px; margin-bottom: 8px;">${item.category || 'Tech'}</span>
      <h2 style="margin: 0 0 8px 0; font-size: 17px; color: #0f172a; font-weight: 700;">
        <a href="${item.url}" style="color: #0f172a; text-decoration: none;">${item.headline}</a>
      </h2>
      <p style="margin: 0 0 10px 0; font-size: 14px; color: #334155; line-height: 1.5;">${item.summary}</p>
      <div style="background-color: #f8fafc; border-left: 3px solid #2563eb; padding: 8px 12px;">
        <p style="margin: 0; font-size: 13px; color: #1e3a8a; font-weight: 600;">💡 <strong>Why It Matters:</strong> ${item.why_it_matters}</p>
      </div>
    </div>
  `;
}

// 2. GitHub Gem
const gem = data.github_gem || {};
const gemHtml = `
  <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; margin-bottom: 16px;">
    <h3 style="margin: 0 0 6px 0; font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #2563eb;">🛠️ GitHub Gem of the Day</h3>
    <p style="margin: 0 0 6px 0; font-size: 15px; font-weight: 700;"><a href="${gem.url || '#'}" style="color: #2563eb; text-decoration: none;">${gem.repo_name || 'Open Source Repo'}</a></p>
    <p style="margin: 0 0 8px 0; font-size: 13px; color: #475569;">${gem.description || ''}</p>
    <div style="background-color: #0f172a; color: #38bdf8; font-family: monospace; padding: 6px 10px; border-radius: 4px; font-size: 12px; margin-bottom: 6px;">${gem.quickstart || ''}</div>
    <p style="margin: 0; font-size: 12px; color: #64748b;"><strong>Why Use It:</strong> ${gem.practical_use || ''}</p>
  </div>
`;

// 3. System Design Card
const sd = data.system_design_card || {};
const bullets = (sd.how_it_works || []).map(b => `<li style="margin-bottom: 4px;">${b}</li>`).join('');
const sdHtml = `
  <div style="background-color: #eff6ff; border: 1px solid #bfdbfe; border-radius: 8px; padding: 16px; margin-bottom: 16px;">
    <h3 style="margin: 0 0 6px 0; font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #1d4ed8;">🧠 System Design Micro-Card</h3>
    <p style="margin: 0 0 6px 0; font-size: 15px; font-weight: 700; color: #1e3a8a;">${sd.topic || 'Distributed Architecture'}</p>
    <p style="margin: 0 0 8px 0; font-size: 13px; color: #1e40af;"><strong>Problem:</strong> ${sd.core_problem || ''}</p>
    <ul style="margin: 0 0 8px 0; padding-left: 20px; font-size: 13px; color: #1e293b;">${bullets}</ul>
    <p style="margin: 0; font-size: 12px; color: #1d4ed8;"><strong>🏢 Case Study:</strong> ${sd.real_world_case || ''}</p>
  </div>
`;

// 4. Terminal Tip
const tip = data.terminal_tip || {};
const tipHtml = `
  <div style="background-color: #f1f5f9; border: 1px solid #cbd5e1; border-radius: 8px; padding: 14px; margin-bottom: 20px;">
    <h3 style="margin: 0 0 4px 0; font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #475569;">💡 Terminal Power-Tip</h3>
    <code style="background-color: #0f172a; color: #a5f3fc; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: bold; display: inline-block; margin-bottom: 6px;">${tip.command || ''}</code>
    <p style="margin: 0; font-size: 13px; color: #334155;">${tip.explanation || ''}</p>
  </div>
`;

const emailHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #f3f4f6; margin: 0; padding: 20px;">
  <div style="max-width: 620px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);
    <div style="background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%); padding: 30px 24px; color: #ffffff;">
      <p style="margin: 0 0 6px 0; font-size: 11px; text-transform: uppercase; letter-spacing: 1.5px; color: #38bdf8;">⚡ Autonomous Developer Intelligence</p>
      <h1 style="margin: 0 0 6px 0; font-size: 24px; font-weight: 800; color: #ffffff;">Morning Tech Pulse</h1>
      <p style="margin: 0; font-size: 13px; color: #94a3b8;">${today} • 3-Min Executive Briefing</p>
    </div>
    <div style="padding: 24px; background-color: #f8fafc;">
      <h3 style="margin: 0 0 14px 0; font-size: 14px; text-transform: uppercase; letter-spacing: 0.5px; color: #64748b;">📰 Top Engineering Breakthroughs</h3>
      ${storiesHtml}
      ${gemHtml}
      ${sdHtml}
      ${tipHtml}
      <div style="text-align: center; padding-top: 16px; border-top: 1px solid #e2e8f0; font-size: 11px; color: #64748b;">
        <p style="margin: 0 0 4px 0;">Curated autonomously by your <strong>n8n Workflow</strong>.</p>
        <p style="margin: 0;">Powered by <strong>Groq Llama-3.3-70B</strong> • $0 Compute Cost</p>
      </div>
    </div>
  </div>
</body>
</html>
`;

const firstHeadline = (data.top_stories && data.top_stories[0]) ? data.top_stories[0].headline : 'Daily Briefing';

return [{
  json: {
    subject: `☕ Morning Tech Pulse: ${firstHeadline} [${today}]`,
    htmlContent: emailHtml
  }
}];
